package com.saasquatch.intelligence; import static org.junit.jupiter.api.Assertions.*; import com.saasquatch.intelligence.entity.*; import com.saasquatch.intelligence.intelligence.*; import org.junit.jupiter.api.Test; class OpportunityScoringEngineTest { @Test void scoreBreakdownUsesDecisionMakerAndGrowth(){Company c=new Company();c.setEstimatedRevenueMillions(120.0);c.setGrowthRate(38.0);c.setTechnologyStack("AWS, React");c.setIndustry("SaaS");Lead l=new Lead();l.setCompany(c);l.setDecisionMaker(true);l.getSignals();l.setDataConfidence(94);var b=new OpportunityScoringEngine().breakdown(l);assertEquals(20,b.revenuePotential());assertEquals(18,b.growth());assertEquals(17,b.technologyFit());assertEquals(15,b.decisionMaker());assertEquals(14,b.industryFit());assertEquals(9,b.dataConfidence());}}